-- Expand-only content safety status and check log (CH-248).
-- Old servers ignore the new columns and table. Existing rows default to
-- UNCHECKED: Web public lists stay unchanged; miniapp public reads hide them.
-- Roll the app back to the previous SHA and leave the table and columns in
-- place. Dropping them must be a new forward migration
-- (docs/Cardhub/development-backlog.md §1.3). Do not edit this file after it
-- lands on main.

CREATE TYPE "ContentSafetyStatus" AS ENUM ('UNCHECKED', 'REVIEW', 'PASS', 'RISKY');

CREATE TYPE "ContentSafetyKind" AS ENUM ('TEXT', 'IMAGE', 'AUDIO');

ALTER TABLE "users"
  ADD COLUMN "wechatOpenid" TEXT,
  ADD COLUMN "miniappLastSeenAt" TIMESTAMP(3);

ALTER TABLE "comments"
  ADD COLUMN "safetyStatus" "ContentSafetyStatus" NOT NULL DEFAULT 'UNCHECKED';

ALTER TABLE "topics"
  ADD COLUMN "safetyStatus" "ContentSafetyStatus" NOT NULL DEFAULT 'UNCHECKED';

ALTER TABLE "replies"
  ADD COLUMN "safetyStatus" "ContentSafetyStatus" NOT NULL DEFAULT 'UNCHECKED';

ALTER TABLE "listings"
  ADD COLUMN "safetyStatus" "ContentSafetyStatus" NOT NULL DEFAULT 'UNCHECKED';

ALTER TABLE "reports"
  ADD COLUMN "safetyStatus" "ContentSafetyStatus" NOT NULL DEFAULT 'UNCHECKED';

CREATE INDEX "comments_safetyStatus_userId_idx" ON "comments"("safetyStatus", "userId");

CREATE INDEX "topics_safetyStatus_userId_idx" ON "topics"("safetyStatus", "userId");

CREATE INDEX "replies_safetyStatus_userId_idx" ON "replies"("safetyStatus", "userId");

CREATE INDEX "listings_safetyStatus_userId_idx" ON "listings"("safetyStatus", "userId");

CREATE INDEX "reports_safetyStatus_reporterId_idx" ON "reports"("safetyStatus", "reporterId");

CREATE TABLE "content_safety_checks" (
    "id" TEXT NOT NULL,
    "actorId" TEXT,
    "actorUsername" TEXT NOT NULL,
    "targetType" TEXT NOT NULL,
    "targetId" TEXT,
    "kind" "ContentSafetyKind" NOT NULL,
    "scene" INTEGER,
    "excerpt" TEXT NOT NULL,
    "result" TEXT NOT NULL,
    "mediaUrl" TEXT,
    "traceId" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "decidedAt" TIMESTAMP(3),

    CONSTRAINT "content_safety_checks_pkey" PRIMARY KEY ("id")
);

ALTER TABLE "content_safety_checks"
  ADD CONSTRAINT "content_safety_checks_excerpt_length_check"
  CHECK (char_length("excerpt") <= 120);

ALTER TABLE "content_safety_checks"
  ADD CONSTRAINT "content_safety_checks_result_check"
  CHECK ("result" IN ('unchecked', 'pass', 'review', 'risky', 'pending'));

CREATE UNIQUE INDEX "content_safety_checks_traceId_key" ON "content_safety_checks"("traceId");

CREATE INDEX "content_safety_checks_targetType_targetId_idx" ON "content_safety_checks"("targetType", "targetId");

CREATE INDEX "content_safety_checks_createdAt_idx" ON "content_safety_checks"("createdAt");

CREATE INDEX "content_safety_checks_actorId_createdAt_idx" ON "content_safety_checks"("actorId", "createdAt");

ALTER TABLE "content_safety_checks"
  ADD CONSTRAINT "content_safety_checks_actorId_fkey"
  FOREIGN KEY ("actorId") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
